VALUES ('bcda3b69-3fa2-52ef-96c7-cc155b4867fb', '2e24e2b4-d375-5dca-9c86-b035a5b3e876', 'id', 'Id', 'The permanent system identity of the address. Generated on creation; parties, locations and document snapshots refer to the address through it.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
