VALUES ('e46d08df-79fb-5587-9dbc-e51931e19398', '2e24e2b4-d375-5dca-9c86-b035a5b3e876', 'is_primary', 'Is Primary', 'Marks the address a party or location uses by default for its address type. Set by the person maintaining addresses; at most one active primary address of each type applies per party or location, and it is the one documents pick unless told otherwise.', 20, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
