VALUES ('c325c819-666c-59e0-99f0-e4c58ba4a30f', '2113101d-3e75-52e3-b373-bfd627d5f7a8', 'code', 'Code', 'The code of the place in the organisation''s site list, such as NL-RTM-DC1. Unique; assigned by the administrator and used in integrations and labels.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
