INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('27a2c68f-fd8c-5aed-986d-178da31a6ca2', 'State Province', 'Maintain State Province records', 'Create, find and maintain State Province records. The list shows every State Province you have access to — select a row to open it, or use New to add one. Each row is a single State Province, described by 5 fields.

Id and Code are unique: no two State Province records may share the same value, and a save that would duplicate one is rejected. Code, Name and Country must be filled in before the record can be saved.

Every State Province points at Country. Choose the linked record from the lookup on those fields rather than typing an identifier. Address and City refer back to State Province, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to State Province then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A State Province with no rules or workflows attached is marked Final immediately.', 'map', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('95a5050f-f683-587f-8974-db7731cfe622', 'bus_state_province', 'State Province', 'A first-level division of a country, such as a state, province or region, from the ISO 3166-2 registry. States and provinces give addresses a standard, checkable subdivision. Choosing from this list avoids misspelt regions and lets reports group by region. Maintained as reference data; chosen in addresses; read by tax, shipping and reports. A state or province belongs to one country and contains cities. Entries are loaded from the standard and rarely change; when a division is abolished it is withdrawn without deleting history. "California" belongs to the United States and contains cities such as Los Angeles. Chosen from the list wherever a record needs a place, code or currency; maintained by an administrator when a registry changes.', 'map', 'A', FALSE, FALSE, FALSE, TRUE, '27a2c68f-fd8c-5aed-986d-178da31a6ca2', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d807553-9ff5-5b24-a27b-79904b064564', '27a2c68f-fd8c-5aed-986d-178da31a6ca2', '95a5050f-f683-587f-8974-db7731cfe622', 'State Province', 'Shows one State Province at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Country is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
