VALUES ('bad566ca-8fa3-56a1-b335-e8f237676054', '48b74a90-07df-5d26-a905-d08e54b825c2', '62ab06d0-7492-5222-aaa6-026f1b398342', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Id', 'The identity of the task, constant for its life. Generated on creation; workflow and audit records refer to it. Must be unique: a save is rejected if another Task already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
