VALUES ('16c1068b-bb96-50d9-8a02-5bd2a34f47ce', '48b74a90-07df-5d26-a905-d08e54b825c2', 'd71c2896-be02-5349-bde5-2e9430ec81f3', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Due At', 'Set when created; overdue tasks are flagged. Compared with the completion time. Records when the due event occurred. It establishes chronology, supports auditability, and helps coordinate related lifecycle and process activities.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
