VALUES ('3679c385-183d-5780-8a54-2103ca6f1d22', 'e33c1297-f514-5071-af7a-9a4462b26f2c', 'code', 'Code', 'The code by which staff and systems name the product. Unique; assigned by product management and used in orders, price lists and integrations.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
