INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3444d249-4c90-54f9-aa99-9ec9d810802d', '15d443c9-ff30-5dae-aa64-d87d59a8eb68', 'product_id', 'Product', 'The product that this bill describes how to make. Chosen when the bill is created; a product can have several bills over time or for alternative ways of making it. Exactly one product: a bill is the recipe for a single finished item. Ties the recipe to the finished item that planning and costing are run for.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b019c01f-0983-54d5-a633-b5304cd5c7a7', 'c407ba5d-e250-5db5-9637-912d4fa7b170', '13c27ede-74e3-5af9-8233-90192bc01050', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Id', 'The identity of the bill, constant across its versions'' editing. Generated on creation; production orders and cost roll-ups refer to the bill through it. Must be unique: a save is rejected if another Bill Of Material already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('20068a50-1b9f-569d-88ea-9a97fd5f9731', 'c407ba5d-e250-5db5-9637-912d4fa7b170', 'dd6ac5d5-7055-5a92-8b04-e41c3b95d172', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Code', 'The reference by which engineering and planning name the bill, such as BOM-1042. Entered when the bill is created and used in searches and documents; unique across bills. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Bill Of Material already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a886a21f-ec14-563d-b5a0-6adfa4ff6bb3', 'c407ba5d-e250-5db5-9637-912d4fa7b170', 'ba93bf4d-1d24-53fe-b091-d46e2d2fcdeb', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Bom Version', 'The revision of the bill, for example 2.0, so earlier production can be traced to the recipe that applied. Incremented by engineering when the components or quantities change; production records the version used. Required — the record cannot be saved while this is empty. Up to 30 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('26b0646e-dd7b-5ca9-8a05-3f1104761cb2', 'c407ba5d-e250-5db5-9637-912d4fa7b170', 'd903e13b-82f3-57f3-a475-dafca65f1547', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Status', 'Whether the bill is still being written, in force for production, or replaced. Moved by engineering; planning and production use ACTIVE bills. Being prepared; not yet usable for production. Released and in force; planning and production may use it. Replaced or withdrawn; kept for history and for orders already produced from it. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
