-- --------------------------------------------------------------------------
-- Work Center (bus_work_center)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f250b5e8-e407-5684-9dcf-0ca89e20fb8b', 'Work Center', 'Maintain Work Center records', 'Create, find and maintain Work Center records. The list shows every Work Center you have access to — select a row to open it, or use New to add one. Each row is a single Work Center, described by 6 fields.

Id and Code are unique: no two Work Center records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Every Work Center points at Location. Choose the linked record from the lookup on those fields rather than typing an identifier. Operation refers back to Work Center, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Work Center then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Work Center with no rules or workflows attached is marked Final immediately.', 'database', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('926a49fb-750c-5718-b6cc-387c2ab630b9', 'bus_work_center', 'Work Center', 'Manufacturing capacity resource used by routing and execution. WorkCenter represents where or by which resource an Operation is performed. Manufacturing planning, scheduling, dispatch, costing, maintenance coordination, and analytics. Operation defines work; Routing sequences work; ManufacturingWorkOrder executes it. Active → temporarily unavailable/maintenance → active or retired. Capacity/status changes revalidate affected schedules and unreleased work without rewriting completed execution.', 'database', 'A', FALSE, FALSE, FALSE, TRUE, 'f250b5e8-e407-5684-9dcf-0ca89e20fb8b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bfce9ba8-4b26-52b7-99cc-ac94a29c80f9', 'f250b5e8-e407-5684-9dcf-0ca89e20fb8b', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'Work Center', 'Shows one Work Center at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Location is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a4328700-10b0-53cb-92cc-40359fd58aaa', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'id', 'Id', 'The permanent identifier of the work center, unchanged if its code or name is revised. Generated on creation; routing operations, schedules, shop-floor reports and costing refer to it. Identifies the capacity resource independently of location or routing. Referenced by routing and production operations.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4ab73c3e-92ed-551e-a4e0-6a52d499c4f8', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'code', 'Code', 'The short code planners and shop-floor staff use to name the work center. Unique; used in routings, scheduling, dispatch lists and integrations, so changes need coordinating with those users. Operational identifier used in manufacturing plans and execution. Unique within its manufacturing context.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d3dc040-e5a4-5232-91fc-4a1fda8ce4d1', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'name', 'Name', 'A descriptive name saying what the work center is, such as Assembly Line 2. Entered by manufacturing engineers; shown in planning screens, schedules and reports beside the code. Communicates the resource function to planners and operators. Complements the stable code.', 10, 300, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('800a8c11-e8ff-5228-a9e7-e48284ce4c15', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'capacity_per_hour', 'Capacity Per Hour', 'The nominal quantity the work center can process or produce in one hour. Optional; the scheduler divides required quantity by it to test whether a schedule is feasible and to estimate duration. Planning assumption for finite or rough-cut scheduling. Actual execution is captured separately.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('77bb2a79-225d-52cb-9b54-ac272fccb7e2', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'status', 'Status', 'Whether the work center can currently be scheduled, is idle, under maintenance or retired. Starts as ACTIVE; maintenance and planning staff move it, and scheduling only loads active work centers. Available and eligible to be scheduled for production. Not currently used but can be reactivated. Out of production for servicing, with its capacity unavailable. Permanently removed from use. A final state. Controls whether new work may be scheduled or executed. Existing historical operations remain valid.', 1035, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('849a9942-aecd-5a2e-82fe-4eb383453343', '926a49fb-750c-5718-b6cc-387c2ab630b9', 'location_id', 'Location', 'Physical or organizational location of the resource. Places manufacturing capacity within the operating network. Scheduling, material staging, and reporting. Optional for virtual or pooled resources. Location eligibility constrains execution.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
