VALUES ('6127258f-4891-5b5f-9ce0-74576dc8ffa4', 'da44c725-f1d6-5212-8326-03e2a61d6621', 'bill_of_material_id', 'Bill Of Material', 'Effective material structure governing planned component demand. Defines expected inputs. Material planning, issue validation, variance and genealogy. Optional for processes without formal BOM. RELEASED work preserves the effective BOM version.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
