INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7697f608-fd68-51dd-9588-1c497ce726c3', 'da44c725-f1d6-5212-8326-03e2a61d6621', 'routing_id', 'Routing', 'Effective process definition governing production execution. Defines ordered operations and resource expectations. Scheduling, execution, costing and audit. Optional for simple production without formal routing. RELEASED work preserves the effective routing version.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ca63ba2c-ada4-59e0-b97f-338df1777e87', '2f017840-7f2a-56a5-8d54-c4304393ef75', '7728bbea-a3f1-5d72-b990-dcb7fbe9acbc', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Id', 'Stable identity of the production order. Identifies one authorized manufacturing execution independently of its business number. Planning, execution, inventory, costing, quality, genealogy, and audit. Root identity for material issues, output receipts and scrap. Must be unique: a save is rejected if another Manufacturing Work Order already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('edf62659-9fe0-5385-ae03-e9cf62b5ec28', '2f017840-7f2a-56a5-8d54-c4304393ef75', '517f57fc-c4a5-56d0-970d-46fb190b751a', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Order Number', 'The reference number people use for this production order on the shop floor and in documents. Allocated by the system on creation; unique, and used in scheduling, material staging, quality checks, costing and audit. Operational identifier used across planning and shop-floor execution. Distinct from inventory transaction references. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Manufacturing Work Order already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc94d2a4-333c-56f8-8755-e9b0bfe2cc20', '2f017840-7f2a-56a5-8d54-c4304393ef75', '3e65df19-8c53-513c-b5c1-a82a4a881227', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Quantity', 'The target quantity of the product that this order is authorised to produce. Set by the planner when the order is created; material planning, capacity and completion variance are all measured against it. Defines planned production magnitude. Interpreted with output Product and UOM policy. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('df98fd98-d2a0-5ec2-9366-91f4c88fc11e', '2f017840-7f2a-56a5-8d54-c4304393ef75', '81f0bc80-a940-503c-b054-99634d50ccfc', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Planned Start', 'The date and time at which production is planned to begin. Set by the planner during scheduling; capacity and material staging are planned from it, and it should not be after the planned end. Scheduling expectation rather than execution evidence. Actual events are recorded separately.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('677a2d8b-300e-5eaa-8dac-7b18849ff62f', '2f017840-7f2a-56a5-8d54-c4304393ef75', 'c4dab14f-374b-51b3-bf29-9bf05127f69b', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Planned End', 'The date and time at which production is planned to be complete. Set by the planner during scheduling; capacity and delivery-promise calculations read it, and it should not be before the planned start. Scheduling target for output availability. Must not precede plannedStart.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bd62ffb0-680d-5b1b-8938-a5a03ae34614', '2f017840-7f2a-56a5-8d54-c4304393ef75', '1216f30f-a4e3-50c3-aa43-67e2ed4d60c2', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Status', 'Where the production order is in its lifecycle, from planning to closure. Moved by planners and shop-floor control; materials are issued and output reported only once the order is released. Being planned and not yet executable. Authorised for execution, so materials may be issued and work started. Execution has begun on the shop floor. Production is materially complete, pending closure where applicable. Reconciled and administratively closed. A final state. Terminated before the remaining execution was done. A final state. Controls authorization and execution eligibility. Posted execution evidence is not reversed by changing header status. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
