-- --------------------------------------------------------------------------
-- Lot (bus_lot)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0071132b-c73e-5e97-b9e6-1945c8378588', 'Lot', 'Maintain Lot records', 'Create, find and maintain Lot records. The list shows every Lot you have access to — select a row to open it, or use New to add one. Each row is a single Lot, described by 6 fields.

Id is unique: no two Lot records may share the same value, and a save that would duplicate one is rejected. Lot Number, Status and Product must be filled in before the record can be saved.

Every Lot points at Product. Choose the linked record from the lookup on those fields rather than typing an identifier. Material Issue, Production Receipt, Serial Number, Inventory Movement and Scrap refer back to Lot, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Lot then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Lot with no rules or workflows attached is marked Final immediately.', 'database', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1634d384-25d6-53bd-a562-3ba10e2edfeb', 'bus_lot', 'Lot', 'Batch-level inventory identity for end-to-end genealogy and recall. Product identifies what an item is; Lot identifies which production or receipt batch a quantity belongs to. Inventory, WMS, manufacturing, quality, procurement, sales fulfillment, expiry management, recall, and regulatory traceability. Lot follows Product quantities through InventoryMovement and InventoryBalance and may later connect to receipt, production, shipment, inspection, and certificate evidence. Created/received → active or quarantined → released/held → consumed/expired/rejected → closed. Status, expiry, or quality changes immediately revalidate availability, reservations, picking, shipment, production consumption, and disposition without altering historical movements.', 'database', 'A', FALSE, FALSE, FALSE, TRUE, '0071132b-c73e-5e97-b9e6-1945c8378588', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ebbc5e49-412b-573b-b031-cfd337a54d8d', '0071132b-c73e-5e97-b9e6-1945c8378588', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'Lot', 'Shows one Lot at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('960201a2-0500-5fc6-ace5-e0ea5a6473fa', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'id', 'Id', 'The identity of the lot, which stays the same if its number is reissued. Generated on creation; balances, movements and inspections refer to it. Identifies the traceability group independently of printed lot number. Groups quantities of one Product across locations and movements.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('747bf114-bd6f-5c64-a581-134c48ad18fd', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'lot_number', 'Lot Number', 'The batch or lot number by which the quantity is traced, as printed on the label. Assigned at production or receipt; unique per product; used for recalls and first-expired-first-out picking. Traceability code used operationally and externally. Uniqueness is governed with Product and organizational policy.', 10, 150, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7a312278-c0c2-5aec-b7d0-6e660aec1740', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'manufactured_at', 'Manufactured At', 'When the lot was produced. Entered at production or from the supplier''s documents; the start of shelf life. Anchors production age and provenance. Distinct from receipt date.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f4ffeddc-40f6-58d3-936b-b759742e0a9e', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'expires_at', 'Expires At', 'When the lot must no longer be used or sold. Calculated from manufacture date and shelf life, or taken from the supplier; stock past it is blocked. Controls eligibility where shelf life applies. Does not itself post inventory movement.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ea405022-11d5-57fb-9bcd-aff10f491207', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'status', 'Status', 'Whether the lot may be used. Set by quality and inventory control; only usable statuses allow picking and shipping. In stock and usable under normal rules. Temporarily blocked, for example during an enquiry; it can be released again. Held apart pending a quality decision. Approved by quality for use. Past its expiry date. A final state. Failed quality checks and not to be used. A final state. Fully used up. A final state. Closed administratively with nothing left to track. A final state. Controls allocation and operational eligibility while preserving stock history. Status restrictions affect availability but do not rewrite movement history.', 1009, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('608b4dd1-7917-5301-8fbd-e88809e9e76d', '1634d384-25d6-53bd-a562-3ba10e2edfeb', 'product_id', 'Product', 'The product that the lot is a batch of. Set when the lot is created. Exactly one product: a lot groups units of a single item. Gives the lot its specification and shelf life. Defines item identity for all lot quantities.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
