VALUES ('b14047ab-c50c-5375-997d-97388d8dbff3', '2f2943ed-f441-5de3-9d83-29dc1033a2a0', 'product_id', 'Product', 'Product whose inventory state is affected. Connects event to product master, units and policies. Exactly one product is affected. Identifies stock item.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
