INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('20512017-55a3-5829-98ab-11e8e1c8aa63', 'Production Record', 'Maintain Production Record records', 'Create, find and maintain Production Record records. The list shows every Production Record you have access to — select a row to open it, or use New to add one. Each row is a single Production Record, described by 7 fields.

Id is unique: no two Production Record records may share the same value, and a save that would duplicate one is rejected. Production Date, Quantity, Status and Product must be filled in before the record can be saved.

Every Production Record points at Product and Location. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Production Record then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Production Record with no rules or workflows attached is marked Final immediately.', 'package', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('31d1677b-a3ff-5832-968b-4c2aab5aa2e2', 'bus_production_record', 'Production Record', 'A recorded quantity of output produced or extracted by an operational process, such as a shift''s output at a site. A production record is the operation''s own account of what it produced, when and where. It lets management track output against plan, verify it before it is relied on, and reject figures that prove wrong, without yet being an accounting entry. Entered by site or production staff; verified by a supervisor; read by planning, reporting and yield analysis. A record names the product produced and may name the location, mining site or work order that produced it. A record is planned, recorded when output is reported, then verified or rejected. A planned record may also be rejected if the run is cancelled. Verified and rejected are final. On 3 March the north pit records 1,850 tonnes of iron ore, which the shift supervisor verifies the next morning.', 'package', 'A', FALSE, FALSE, FALSE, TRUE, '20512017-55a3-5829-98ab-11e8e1c8aa63', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1104c267-0bf1-5094-9ecd-5780506faa81', '20512017-55a3-5829-98ab-11e8e1c8aa63', '31d1677b-a3ff-5832-968b-4c2aab5aa2e2', 'Production Record', 'Shows one Production Record at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product and Location are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
