VALUES ('f411427c-4090-58c5-8241-0d837c48fc86', '31d1677b-a3ff-5832-968b-4c2aab5aa2e2', 'id', 'Id', 'The identity of the production record, constant for its life. Generated on creation; other records refer to it. Referenced by anything that reports or verifies this output.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
