VALUES ('96186c35-8f7c-5aed-bbb9-6e8ea947fef2', 'b74eb956-5a6f-5474-aa1d-78a0b478dd21', 'product_id', 'Product', 'A scrap record is for one product; scrap of several products is recorded separately. Material or output being scrapped. Identifies the item affected. Inventory, costing, quality and analysis. Must reconcile with work-order input/output context or approved exception.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
