VALUES ('6a691727-2f88-54fb-b899-ff571ac0893e', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', '7f10d8d1-046d-5c91-856a-beb45109f16c', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Id', 'The identity of the scrap record, constant for its life. Identifies one governed production loss/disposition. Manufacturing, inventory, costing, quality, and audit. Links work order/product quantity to cause and inventory effect. Must be unique: a save is rejected if another Scrap already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('06d02ad0-d247-5ae8-9788-9b41b4d0f6be', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', 'cad32ebd-8be0-5c5c-a3b3-51ee559b420b', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Scrap Number', 'The number of the scrap record, such as SCR-0412. Operational identifier for production loss. Shop-floor reporting, quality, costing and audit. Distinct from inventory movement reference. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Scrap already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c89b0ff8-bb1d-5711-8d9d-dadd94790191', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', '9a40fcb4-5e75-5dcc-9e67-eb856a77bfa4', '41abaa9c-0dad-5f0e-acc0-9e0ac62da776', 'Quantity', 'The amount of material or output written off as scrap in this record. Entered by the operator or supervisor; reduces inventory, feeds yield and variance reports, and is costed as production loss. Quantifies governed production loss or rejected material. Interpreted with Product/UOM/lot/serial context. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('69e12cfb-f6a4-5842-9c81-d5aae0939fa5', '85ea5b94-1e91-59f6-be65-caf1b822cdfa', '56c12d4a-f7dd-5987-bd72-8ff07740408f', '1bc25fc8-c746-5e6b-a6c2-ec36ef103e34', 'Reason Code', 'The coded reason the material was scrapped, such as damaged, out of tolerance or contaminated. Chosen from the governed list when scrap is recorded; quality analysis and improvement work group losses by it. Classifies why material/output was lost or rejected. Should align with controlled reason taxonomy. Required — the record cannot be saved while this is empty. Up to 100 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
