VALUES ('9e7be4c5-7479-57ac-8d2c-2fbceaf47117', 'bus_currency_status', 'Currency Status', 'The values of currency status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, 'e8c3a3f5-45d3-5be9-9e14-c673fefdf6df', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
