INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6efc677d-f351-5a5e-b9e7-bb81be6b9c4d', 'Product Lifecycle Lifecycle Status', 'Maintain Product Lifecycle Lifecycle Status records', 'Create, find and maintain Product Lifecycle Lifecycle Status records. The list shows every Product Lifecycle Lifecycle Status you have access to — select a row to open it, or use New to add one. Each row is a single Product Lifecycle Lifecycle Status, described by 6 fields.

Id and Code are unique: no two Product Lifecycle Lifecycle Status records may share the same value, and a save that would duplicate one is rejected. Code, Name, Sequence and Is Active must be filled in before the record can be saved.

Every save starts as a Draft. The business rules and workflows attached to Product Lifecycle Lifecycle Status then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Product Lifecycle Lifecycle Status with no rules or workflows attached is marked Final immediately.', 'list', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d09f2378-ddba-5559-b813-43f6e388f050', 'bus_product_lifecycle_lifecycle_status', 'Product Lifecycle Lifecycle Status', 'The values of product lifecycle lifecycle status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '6efc677d-f351-5a5e-b9e7-bb81be6b9c4d', 'U', TRUE, 'system', 'system', NOW(), NOW())
